/// <summary>
/// MPJ_25205 Customer aging report DCP 15 06 2022
/// </summary
[ExtensionOf(classStr(CustBalanceList))]
final class METCustBalanceList_Extension
{
    public CustVendAgingProcessingTmp          metCustVendAgingProcessingTmp;
    public CustVendAgingProcessingDetailsTmp   metCustVendAgingProcessingDetailsTmp;

}

Method.Source:
    /// <summary>
    /// rebuild temp tables
    /// </summary>
    /// <param name = "_queryRun">Query</param>
    /// <param name = "_transactionsQuery">Query</param>
    public void  metAgingProcessing(QueryRun _queryRun, Query _transactionsQuery = null)
    {

        CustAgingCalculation        metCustAgingCalculation;

        metCustAgingCalculation = this.instantiateAgingCalculation(_queryRun, _transactionsQuery);

        metCustAgingCalculation.metInsertCustVendData();
        
        metCustVendAgingProcessingTmp = metCustAgingCalculation.METSelectTransactions();

        metCustVendAgingProcessingDetailsTmp = metCustAgingCalculation.METSelectDetailsOfTransactions(metCustVendAgingProcessingTmp);

        metCustAgingCalculation.METPreProcess(metCustVendAgingProcessingTmp, metCustVendAgingProcessingDetailsTmp);

    }

/// <summary>
/// return temp table
/// </summary>
/// <returns>Temp table</returns>
public CustVendAgingProcessingTmp metGetCustVendAgingProcessingTmp()
{
    return metCustVendAgingProcessingTmp;
}

/// <summary>
/// return temp table
/// </summary>
/// <returns>Temp table</returns>
public CustVendAgingProcessingDetailsTmp metGetCustVendAgingProcessingDetailsTmp()
{
    return metCustVendAgingProcessingDetailsTmp;
}

/// <summary>
/// return temp table
/// </summary>
/// <returns>Temp table</returns>
public CustVendAgingPeriodScaleTmp metGetAgingPeriodScaleTmp()
{
    return AgingPeriodScaleTmp;
}

    /// <summary>
    /// return temp table
    /// </summary>
    /// <param name = "_bucket">aging bucket</param>
    /// <returns>Report Column number</returns>
    public METBalanceColumn metGetBalanceColumn(Counter _bucket)
    {
        Counter             counter;
        METBalanceColumn    balanceColumn;

        if (direction == ForwardBackwardPrinting::Backward)
        {
            counter = agingBucketCount - _bucket + 1;
        }
        else
        {
            counter = _bucket + 1;
        }

        switch(counter)
        {
            case 1:
                balanceColumn = METBalanceColumn::Balance01;
                break;
            case 2:
                balanceColumn = METBalanceColumn::Balance02;
                break;
            case 3:
                balanceColumn = METBalanceColumn::Balance03;
                break;
            case 4:
                balanceColumn = METBalanceColumn::Balance04;
                break;
            case 5:
                balanceColumn = METBalanceColumn::Balance05;
                break;
            case 6:
                balanceColumn = METBalanceColumn::Balance06;
                break;
            case 7:
                balanceColumn = METBalanceColumn::Balance07;
                break;
        }

        return balanceColumn;
    }

/// <summary>
/// get printing direction
/// </summary>
/// <returns>printing direction</returns>
public ForwardBackwardPrinting metGetDirection()
{
    return this.direction;
}
